package com.oms.order.service;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import com.ruoyi.common.core.constant.SecurityConstants;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Bounded durable compensation; no guessed refund quantities, new orders, or payments. */
@Service public class RefundParcelAutomation {
    @Resource RefundService refunds;
    @Resource RefundParcelPolicy policies;
    @Resource RefundParcelWorkspace parcels;
    @Resource RefundGoodsService goods;
    @Resource RefundReturnClient returns;
    @Resource RefundReturnDispatchAutomation dispatcher;
    private OrderRepository r(){return refunds.repository;}
    static String carrier(String raw){String s=raw.trim().toUpperCase(Locale.ROOT);Map<String,String> aliases=new HashMap<>();for(String x:Arrays.asList("SF","顺丰","顺丰快递","顺丰速运"))aliases.put(x,"SF");for(String x:Arrays.asList("STO","申通","申通快递"))aliases.put(x,"STO");for(String x:Arrays.asList("YTO","圆通","圆通速递","圆通快递"))aliases.put(x,"YTO");for(String x:Arrays.asList("ZTO","中通","中通快递"))aliases.put(x,"ZTO");for(String x:Arrays.asList("YUNDA","韵达","韵达快递"))aliases.put(x,"YUNDA");for(String x:Arrays.asList("EMS","邮政EMS"))aliases.put(x,"EMS");String result=aliases.get(s);require(result!=null,"承运商未能明确映射，请人工核实快递编码");return result;}
    public void scan(String c){List<Long> ids=r().db().queryForList("SELECT b.id FROM oms_refund_parcel_config cfg JOIN oms_refund b ON b.company_code=cfg.company_code AND b.channel_id=cfg.channel_id JOIN oms_refund_return_plan p ON p.company_code=b.company_code AND p.refund_id=b.id WHERE cfg.company_code=? AND ((cfg.enabled=1 AND cfg.auto_enabled=1) OR (cfg.auto_dispatch=1 AND p.state='PLANNED' AND p.auto_dispatch_state<>'FAILED')) AND b.review_state='APPROVED' AND (b.goods_state<>'DONE' OR p.gift_plan_id IS NOT NULL) AND p.state NOT IN ('CLOSED','RELEASED','STOPPED') AND p.parcel_next_attempt<=NOW() GROUP BY b.id ORDER BY MIN(p.parcel_next_attempt),b.id LIMIT 30",Long.class,c);for(Long id:ids)process(c,id);}
    public void process(String c,long refund){Map<String,Object> b=refunds.business(c,refund,false),policy=policies.get(c,number(b,"channel_id"));if(number(policy,"auto_enabled")!=1||number(policy,"enabled")!=1){if(dispatcher!=null)dispatcher.process(c,refund);return;}
        for(Map<String,Object> plan:r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND state NOT IN ('CLOSED','STOPPED','RELEASED') ORDER BY id LIMIT 100",ROW,c,refund)){
            long id=number(plan,"id");String lease=token();if(r().db().update("UPDATE oms_refund_return_plan SET parcel_lease_token=?,parcel_lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (parcel_lease_until IS NULL OR parcel_lease_until<NOW())",lease,c,id)!=1)continue;
            try{Map<String,Object> fresh=r().db().query("SELECT * FROM oms_refund_return_plan WHERE company_code=? AND id=?",ROW,c,id).get(0);if(!Arrays.asList("WAIT_BUYER","WAREHOUSE_CHECK","SUPPLEMENTED","MANUAL_LINKED").contains(text(fresh,"parcel_resolution")))link(c,refund,fresh,policy,lease);}catch(RuntimeException failure){String why=(failure instanceof IllegalArgumentException||failure instanceof IllegalStateException)?failure.getMessage():"自动合包暂未完成，请核对服务状态后重试";state(c,refund,id,lease,"NEED_CHECK",why==null?"自动合包失败":why,failure instanceof RefundParcelIssues.Issue?((RefundParcelIssues.Issue)failure).detail:m("code","RULE_BLOCKED","title","合包待核对","reason",why,"next_action","核对物流、店铺规则及仓库能力后重新检查"));}
            finally{r().db().update("UPDATE oms_refund_return_plan SET parcel_next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND),parcel_lease_token=NULL,parcel_lease_until=NULL WHERE company_code=? AND id=? AND parcel_lease_token=?",c,id,lease);}
        }
        if(dispatcher!=null)dispatcher.process(c,refund);
    }
    @SuppressWarnings("unchecked") private void link(String c,long refund,Map<String,Object> plan,Map<String,Object> policy,String lease){long id=number(plan,"id");fence(c,id,lease);Map<String,Object> b=refunds.business(c,refund,false),p=refunds.platform(c,number(b,"platform_refund_id"),false);
        if(!"APPROVED".equals(text(b,"review_state"))||number(b,"approved_version")!=number(p,"version")||!"VALID".equals(text(p,"source_state"))||"CLOSED".equals(text(p,"platform_status"))||"DONE".equals(text(b,"goods_state"))&&plan.get("gift_plan_id")==null){state(c,refund,id,lease,"WAIT_REVIEW","等待当前可信平台方案审核，或申请已关闭");return;}
        String source="MANUAL".equals(text(plan,"logistics_source"))?"MANUAL":"PLATFORM";require(RefundParcelPolicy.values(policy,"logistics_sources").contains(source),"当前物流来源未被自动合包配置允许");
        Map<String,Object> raw="PLATFORM".equals(source)?parse(text(p,"payload")):Collections.emptyMap();String waybill="MANUAL".equals(source)?text(plan,"return_waybill"):text(raw,"sid");String name="MANUAL".equals(source)?text(plan,"return_carrier"):text(raw,"company_name");
        if(waybill.isEmpty()||name.isEmpty()){state(c,refund,id,lease,"WAIT_LOGISTICS","等待平台退回物流，或人工核实登记");return;}String carrier="MANUAL".equals(source)?name.toUpperCase(Locale.ROOT):carrier(name);require(carrier.matches("[A-Z0-9_-]{1,50}"),"人工核实的快递编码无效");
        String store=plan.get("result_json")==null?text(plan,"store_code"):text(obj(plan.get("result_json")),"store_code");require(RefundParcelPolicy.values(policy,"store_codes").contains(store),"当前退回仓未纳入自动合包配置");
        List<Map<String,Object>> existing=data(returns.parcels(c,refund,SecurityConstants.INNER));Map<String,Object> bound=null;long generation=plan.get("result_json")==null?1:number(obj(plan.get("result_json")),"generation");
        for(Map<String,Object> parcel:existing)for(Map<String,Object> member:(List<Map<String,Object>>)parcel.get("members"))if(number(member,"plan_id")==id&&number(member,"generation")==generation&&(bound==null||number(parcel,"id")>number(bound,"id")))bound=parcel;
        if(bound!=null){require(carrier.equals(text(bound,"carrier_code"))&&waybill.equals(text(bound,"waybill"))&&store.equals(text(bound,"store_code")),"退回物流已变化；保留原包裹和仓库单，请截单核对后重新安排");}
        else{
            List<Map<String,Object>> candidates=data(returns.parcelCandidates(c,carrier,waybill,SecurityConstants.INNER));Map<String,Object> command=m("control_version",b.get("control_version"),"plan_version",plan.get("control_version"),"carrier_code",carrier,"waybill",waybill,"confirmed",true,"reason","同店铺、同原平台订单、同承运商运单、同退回仓；配置版本 "+policy.get("revision"),"evidence",source+" / 平台退款 "+b.get("refund_id")+" / 来源版本 "+p.get("version"));
            if(!candidates.isEmpty()){Map<String,Object> candidate=candidates.get(0);require(number(candidate,"channel_id")==number(b,"channel_id")&&text(candidate,"platform_tid").equals(text(b,"platform_tid"))&&text(candidate,"store_code").equals(store),"相同运单的店铺、原平台订单或退回仓不一致，请核对真实物流");if(number(candidate,"receipt_count")>0)throw new RefundParcelIssues.Issue(RefundParcelIssues.afterReceipt(candidate));if(number(candidate,"dispatched")>0){Map<String,Object> issue=RefundParcelIssues.afterReceipt(candidate);issue.put("code","THK_FROZEN");issue.put("title","共同THK范围已冻结");issue.put("reason","相同运单已有共同THK下发，不能静默新增来源或另建独立THK");issue.put("next_action","核对原包裹与共同THK；确有新增商品请转仓库差异核对，实际另包请更正物流");throw new RefundParcelIssues.Issue(issue);}command.put("join_parcel_id",candidate.get("id"));}
            fence(c,id,lease);parcels.attach(c,refund,id,command,"自动合包",true);
        }
        fence(c,id,lease);state(c,refund,id,lease,"LINKED","");
    }

    private void fence(String c,long plan,String lease){require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND id=? AND parcel_lease_token=? AND parcel_lease_until>NOW()",Long.class,c,plan,lease)==1,"自动合包租约已失效，等待当前任务处理");}
    private void state(String c,long refund,long plan,String lease,String state,String error){state(c,refund,plan,lease,state,error,null);}
    private void state(String c,long refund,long plan,String lease,String state,String error,Map<String,Object> issue){String why=error.substring(0,Math.min(500,error.length()));String encoded=issue==null?null:encode(issue);int changed=r().db().update("UPDATE oms_refund_return_plan SET parcel_state=?,parcel_error=?,parcel_issue=? WHERE company_code=? AND id=? AND parcel_lease_token=? AND parcel_lease_until>NOW() AND (parcel_state<>? OR parcel_error<>? OR NOT (parcel_issue <=> CAST(? AS JSON)))",state,why,encoded,c,plan,lease,state,why,encoded);if(changed>0)refunds.event(c,refund,"PARCEL_AUTO","退回计划 #"+plan+"："+text(m("LINKED","已关联退回包裹","WAIT_LOGISTICS","等待退回物流","WAIT_REVIEW","等待审核","NEED_CHECK","合包待核对"),state)+(why.isEmpty()?"":"；"+why),"自动合包");}
    public void manual(String c,long refund,long plan,Map<String,Object> body,String actor){refunds.tx().execute(tx->{Map<String,Object> b=refunds.business(c,refund,true);require(number(body,"control_version")==number(b,"control_version")&&Boolean.TRUE.equals(body.get("confirmed")),"请刷新并确认已核实寄回物流");require((!"DONE".equals(text(b,"goods_state"))||r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND id=? AND gift_plan_id IS NOT NULL",Long.class,c,refund,plan)==1)&&"APPROVED".equals(text(b,"review_state")),"请先核对当前退款审核与货物状态");Map<String,Object> policy=policies.get(c,number(b,"channel_id"));require(number(policy,"auto_enabled")==1&&RefundParcelPolicy.values(policy,"logistics_sources").contains("MANUAL"),"店铺未开启人工核实物流的自动合包");String carrier=required(body,"carrier_code",50).toUpperCase(Locale.ROOT),waybill=required(body,"waybill",50),reason=required(body,"reason",500),evidence=required(body,"evidence",1000);require(carrier.matches("[A-Z0-9_-]{1,50}")&&waybill.matches("[A-Za-z0-9_-]{1,50}"),"快递编码或运单格式无效");require(r().db().update("UPDATE oms_refund_return_plan SET return_carrier=?,return_waybill=?,logistics_source='MANUAL',transport_evidence=?,parcel_resolution='',parcel_issue=NULL,parcel_state='WAIT_LOGISTICS',parcel_error='',parcel_next_attempt=NOW(),control_version=control_version+1 WHERE company_code=? AND refund_id=? AND id=? AND control_version=? AND (lease_until IS NULL OR lease_until<NOW())",carrier,waybill,evidence,c,refund,plan,body.get("plan_version"))==1,"退回计划已变化或正在处理，请刷新");refunds.event(c,refund,"PARCEL_LOGISTICS","人工核实退回物流 "+carrier+" / "+waybill+"；"+reason+"；凭证："+evidence,actor);return null;});process(c,refund);}
}
